def transform(grid):
    bg = grid[0][0]
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    if w == 0:
        return []

    # Find all columns with at least one non-bg pixel
    non_bg_cols = set()
    for c in range(w):
        for r in range(h):
            if grid[r][c] != bg:
                non_bg_cols.add(c)

    if not non_bg_cols:
        return [[bg] * w for _ in range(h)]

    sorted_cols = sorted(non_bg_cols)
    result = [[bg] * len(sorted_cols) for _ in range(h)]

    # Copy non-bg pixels to output
    for c, sc in zip(sorted_cols, range(len(sorted_cols))):
        for r in range(h):
            if grid[r][c] != bg:
                result[r][sc] = grid[r][c]

    return result
